CREATE TABLE IF NOT EXISTS audit_area (
  id SERIAL PRIMARY KEY,
  name VARCHAR(500) NOT NULL
);

ALTER TABLE compliance_task
  ADD COLUMN IF NOT EXISTS priority VARCHAR(50),
  ADD COLUMN IF NOT EXISTS risk_category VARCHAR(50),
  ADD COLUMN IF NOT EXISTS business_risk VARCHAR(50),
  ADD COLUMN IF NOT EXISTS control_risk VARCHAR(50),
  ADD COLUMN IF NOT EXISTS audit_area_id INTEGER REFERENCES audit_area(id);

